// Authorization server: refresh endpoint (simplified)
public async Task<IActionResult> Refresh(string presentedToken)
{
    var record = await _tokens.FindAsync(presentedToken);
    if (record is null || record.RevokedAt is not null)
        return Unauthorized();

    if (record.RotatedAt is not null)
    {
        // Replay of an already-rotated token → assume theft,
        // kill the entire session lineage.
        await _tokens.RevokeFamilyAsync(record.FamilyId);
        return Unauthorized();
    }

    var next = RefreshToken.Create(familyId: record.FamilyId);
    record.RotatedAt = DateTime.UtcNow;       // invalidate the old one
    await _tokens.AddAsync(next);             // new refresh token
    await _tokens.SaveChangesAsync();

    // New short-lived access token issued alongside
    var access = await _tokens.IssueAccessTokenAsync(record.UserId);
    return Ok(new { accessToken = access, refreshToken = next.Value });
}

// Client rules:
// - access token in memory only; refresh via HttpOnly cookie (web) or Keychain (mobile)
// - on 401, attempt one refresh; queue/deduplicate concurrent refreshes
// - never send the refresh token to resource APIs
